int _fixedAssetCollectionEstimateSize(
  FixedAssetCollection object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  bytesCount += 3 + object.assetCode.length * 3;
  bytesCount += 3 + object.categoryId.length * 3;
  {
    final value = object.custodianId;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.depreciationMethod.length * 3;
  bytesCount += 3 + object.groupId.length * 3;
  {
    final value = object.insurancePolicyNumber;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  {
    final value = object.locationId;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.name.length * 3;
  bytesCount += 3 + object.status.length * 3;
  bytesCount += 3 + object.uuid.length * 3;
  return bytesCount;
}

